// Both outputs of "Call CRM" land here: an HTTP response (any status) or a network error/timeout.
const { nextStep } = __require('./retry');
const ctx = $('Prepare request').last().json; // this execution handles exactly one request
const isError = $json.error !== undefined && $json.statusCode === undefined;
const step = isError
  ? nextStep({ error: $json.error, attempt: ctx.attempt, maxAttempts: ctx.max_attempts })
  : nextStep({ statusCode: $json.statusCode, headers: $json.headers, attempt: ctx.attempt, maxAttempts: ctx.max_attempts });
const response = isError ? null : {
  status: $json.statusCode,
  body: $json.body,
  headers: { 'retry-after': $json.headers?.['retry-after'] ?? null, 'idempotent-replay': $json.headers?.['idempotent-replay'] ?? null },
};
return {
  json: {
    ...ctx,
    response,
    step,
    history: [...ctx.history, { attempt: ctx.attempt, status: response ? response.status : null, decision: step.decision, reason: step.reason, delay_ms: step.delayMs }],
  },
};

// WF-11: one CRM call with the retry policy from src/retry.js (C-23).
// Input:  { request: { method, path, body?, headers? }, context?, max_attempts? }
// Output: { ok, status, body, error_code, attempts, history, idempotent_replay, context }
const req = $json.request || {};
if (!req.method || !req.path) throw new Error('WF-11 needs request.method and request.path');
return {
  json: {
    request: {
      method: String(req.method).toUpperCase(), path: req.path, body: req.body ?? null,
      headers: { ...(req.body != null ? { 'content-type': 'application/json' } : {}), ...(req.headers || {}) },
    },
    url: 'http://crm:3000' + req.path,
    // Strings are built here, in plain JavaScript; the HTTP node only references fields.
    has_body: req.body != null,
    body_json: JSON.stringify(req.body ?? null),
    headers_json: JSON.stringify({ ...(req.body != null ? { 'content-type': 'application/json' } : {}), ...(req.headers || {}) }),
    context: $json.context ?? null,
    attempt: $json.attempt || 1,
    max_attempts: $json.max_attempts || 5,
    history: $json.history || [],
  },
};

const s = $json.step;
const r = $json.response;
return {
  json: {
    ok: s.decision === 'ok',
    status: r ? r.status : null,
    body: r ? r.body : null,
    error_code: s.decision === 'ok' ? null : s.decision === 'give_up' ? 'RETRIES_EXHAUSTED_' + s.reason : s.reason,
    attempts: $json.attempt,
    history: $json.history,
    idempotent_replay: r ? r.headers['idempotent-replay'] === 'true' : false,
    context: $json.context,
  },
};
